    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Lattice shuffles and their signs", H("Lattice shuffles and their signs"), Blocks(
        Paragraph(Text("A (p,q)-shuffle is an injective monotone map from Fin(p+q+1) to Fin(p+1) × Fin(q+1). All degrees p and q are arbitrary natural numbers. The coordinate sum at vertex r is r, so each edge increases exactly one coordinate by one. The inversion count sums the second coordinate before every first-coordinate step, and the integer sign is (-1) to this count.")),
        Paragraph(Text("Swapping the two coordinates exchanges the two degrees. The two inversion counts sum to p*q, giving the Koszul factor (-1)^(p*q). The staircase path k ↦ (min(k,p),k-p) has sign 1. When either degree is zero there is a unique shuffle. Finiteness of each shuffle set is used only for finite sums; there is no bound on the degrees.")),
